begin read only;
select jsonb_build_object('at',clock_timestamp(),'v2',(select to_jsonb(c)from spot_private.soma_v2_control c),'retention',(select to_jsonb(c)from spot_private.retention_phase_a_control c),'analytics',(select to_jsonb(c)from spot_private.analytics_control c),'notifications',(select to_jsonb(c)from spot_private.notification_control c),'ops',(select to_jsonb(c)from spot_private.ops_control c),'photo',(select jsonb_build_object('phase',phase,'execute_enabled',execute_enabled,'scheduler_enabled',scheduler_enabled)from spot_private.photo_cutover_control),'policies',(select jsonb_agg(to_jsonb(p))from spot_private.retention_policies p),'bucket',(select jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types))from storage.buckets),'consent_versions',(select jsonb_agg(jsonb_build_object('version',version,'status',status,'required',required))from spot_private.consent_versions),'operational_roles',(select count(*)from spot_private.moderation_roles where active),'jobs',(select jsonb_agg(jsonb_build_object('name',jobname,'schedule',schedule,'active',active))from cron.job));
rollback;
